const options={source:['Manual','Instagram','Threads','TikTok','Other'],difficulty:['Not set','Easy','Moderate','Hard'],rating:[0,1,2,3,4,5]};
const variants={hybrid:{source:'Instagram',difficulty:'Moderate',rating:4},sheets:{source:'Instagram',difficulty:'Moderate',rating:4}};
const state={view:'hybrid',layer:null,trigger:null}; const app=document.querySelector('#app-root'),layers=document.querySelector('#layer-root'),note=document.querySelector('#review-note'),compare=document.querySelector('#comparison-stage'),live=document.querySelector('#live-region'); let gesture;
const rating=value=>value?`${value} out of 5`:'Not rated'; const selected=(key,value)=>key==='rating'?rating(value):value;
function announce(text){live.textContent='';requestAnimationFrame(()=>live.textContent=text);}
function selectField(key,value){return `<label>${key[0].toUpperCase()+key.slice(1)}<button class="field-button" type="button" data-open="${key}" aria-haspopup="dialog" aria-label="${key[0].toUpperCase()+key.slice(1)}, ${selected(key,value)}"><span>${selected(key,value)}</span><span class="disclosure" aria-hidden="true">⌄</span></button></label>`;}
function hybrid(values){return `<div class="basics-grid"><label class="full-width">Recipe title<input name="title" value="Smoky Tomato & Butter Bean Stew"></label>${selectField('source',values.source)}<label>Author<input name="author" value="Marta Cooks"></label><label>Cooking time<input name="time" value="45 min"></label><label>Servings<input name="servings" value="4"></label><div class="wide-choice"><div class="choice-heading"><span>Difficulty</span>${values.difficulty!=='Not set'?'<button class="clear-action" type="button" data-clear="difficulty">Clear</button>':''}</div><div class="segmented" role="group" aria-label="Difficulty">${options.difficulty.slice(1).map(value=>`<button type="button" data-set="difficulty:${value}" aria-pressed="${values.difficulty===value}">${value}</button>`).join('')}</div></div><div class="wide-choice"><div class="choice-heading"><span>Personal rating <span class="visually-hidden">${rating(values.rating)}</span></span>${values.rating?'<button class="clear-action" type="button" data-clear="rating">Clear</button>':''}</div><div class="rating-row" role="group" aria-label="Personal rating">${[1,2,3,4,5].map(value=>`<button type="button" class="star-button${value<=values.rating?' is-selected':''}" data-set="rating:${value}" aria-pressed="${value===values.rating}" aria-label="Rate ${value} out of 5">${value<=values.rating?'★':'☆'}</button>`).join('')}</div></div></div>`;}
function sheets(values){return `<div class="basics-grid"><label class="full-width">Recipe title<input name="title" value="Smoky Tomato & Butter Bean Stew"></label>${selectField('source',values.source)}<label>Author<input name="author" value="Marta Cooks"></label><label>Cooking time<input name="time" value="45 min"></label><label>Servings<input name="servings" value="4"></label>${selectField('difficulty',values.difficulty)}${selectField('rating',values.rating)}</div>`;}
function editor(variant=state.view){const values=variants[variant];return `<header class="compact-edit-header"><button class="header-icon" type="button" aria-label="Back to recipe">‹</button><strong class="recipe-title">Smoky Tomato & Butter Bean Stew</strong><button class="save-action" type="button" aria-label="Save recipe">Save</button><button class="header-icon overflow-trigger" type="button" aria-label="More recipe actions">•••</button></header><main class="editor-scroll"><section class="accordion-section is-expanded"><button class="section-toggle" type="button" aria-expanded="true"><span><strong>Basics</strong><small>7 fields</small></span><span class="chevron" aria-hidden="true">⌃</span></button><div class="section-panel basics-form" id="basics-panel">${variant==='hybrid'?hybrid(values):sheets(values)}</div></section><section class="accordion-section"><button class="section-toggle" type="button" aria-expanded="false"><span><strong>Ingredients</strong><small>12 of 50</small></span><span class="chevron" aria-hidden="true">⌄</span></button></section><section class="accordion-section"><button class="section-toggle" type="button" aria-expanded="false"><span><strong>Instructions</strong><small>8 steps</small></span><span class="chevron" aria-hidden="true">⌄</span></button></section></main><nav class="global-navigation" aria-label="Main navigation"><button aria-current="page"><b aria-hidden="true">☰</b><span>Recipes</span></button><button><b aria-hidden="true">▦</b><span>Collections</span></button><button class="global-add" aria-label="Add recipe">+</button><button><b aria-hidden="true">●</b><span>Notifications</span></button><button><b aria-hidden="true">○</b><span>Profile</span></button></nav>`;}
function renderNote(){note.innerHTML=state.view==='hybrid'?'<h2>A · Hybrid controls <small>(recommended)</small></h2><ul><li>Source uses a short, checked selection sheet.</li><li>Difficulty stays visible as three direct choices.</li><li>Rating is one-tap per star and exposes its numeric value.</li></ul><p>Best when speed matters for the frequent, small option sets.</p>':'<h2>B · Consistent selection sheets</h2><ul><li>Source, Difficulty, and Rating use the same field-and-sheet pattern.</li><li>Every value is read before its options open.</li><li>Selections use large checked rows.</li></ul><p>Most consistent, but Difficulty and Rating each add a step.</p>';}
function render(){const comparison=state.view==='compare';document.querySelector('.stage').hidden=comparison;compare.hidden=!comparison;if(comparison){compare.innerHTML=['hybrid','sheets'].map(variant=>`<article class="comparison-card"><h2>${variant==='hybrid'?'A · Hybrid controls':'B · Selection sheets'}</h2><p>${variant==='hybrid'?'Direct Difficulty and Rating controls reduce selection steps.':'One familiar sheet pattern keeps every selection consistent.'}</p><div class="phone"><div class="phone-notch"></div><section class="mobile-edit-surface">${editor(variant)}</section></div></article>`).join('');return;}app.innerHTML=editor();renderNote();}
function renderSheet(){if(!state.layer){layers.replaceChildren();return;}const values=variants[state.view],title=state.layer==='source'?'Select source':state.layer==='difficulty'?'Select difficulty':'Select personal rating';layers.innerHTML=`<div class="sheet-backdrop" data-close></div><section class="bottom-sheet" role="dialog" aria-modal="true" aria-labelledby="sheet-title"><div class="sheet-handle" aria-hidden="true"></div><header><h2 id="sheet-title">${title}</h2><button type="button" data-close aria-label="Close">×</button></header><div class="sheet-body">${options[state.layer].map(value=>`<button class="option-row" type="button" data-value="${value}" aria-pressed="${values[state.layer]===value}"><span>${selected(state.layer,value)}</span>${values[state.layer]===value?'<span class="checkmark" aria-label="Selected">✓</span>':''}</button>`).join('')}</div></section>`;requestAnimationFrame(()=>layers.querySelector('[data-close]')?.focus());}
function open(key,trigger){state.layer=key;state.trigger=trigger;app.inert=true;renderSheet();} function close(){const target=state.trigger;state.layer=null;app.inert=false;renderSheet();requestAnimationFrame(()=>target?.focus());}
app.addEventListener('click',event=>{const button=event.target.closest('button');if(!button)return;if(button.dataset.open){open(button.dataset.open,button);return;}if(button.dataset.set){const [key,value]=button.dataset.set.split(':');variants.hybrid[key]=key==='rating'?Number(value):value;announce(`${key==='rating'?'Personal rating':'Difficulty'} set to ${selected(key,variants.hybrid[key])}`);render();return;}if(button.dataset.clear){const key=button.dataset.clear;variants.hybrid[key]=key==='rating'?0:'Not set';announce(`${key==='rating'?'Personal rating':'Difficulty'} cleared`);render();}});
layers.addEventListener('click',event=>{const button=event.target.closest('button,[data-close]');if(!button)return;if(button.hasAttribute('data-close')){close();return;}if(button.dataset.value!==undefined){const key=state.layer;variants[state.view][key]=key==='rating'?Number(button.dataset.value):button.dataset.value;announce(`${key==='rating'?'Personal rating':key} set to ${selected(key,variants[state.view][key])}`);close();render();}});
layers.addEventListener('pointerdown',event=>{if(event.target.closest('.sheet-handle'))gesture={y:event.clientY,time:performance.now()};});layers.addEventListener('pointerup',event=>{if(!gesture)return;const distance=event.clientY-gesture.y,velocity=distance/Math.max(1,performance.now()-gesture.time);gesture=null;if(distance>=96||velocity>=.65)close();});
document.querySelector('.prototype-toolbar').addEventListener('click',event=>{const button=event.target.closest('[data-view]');if(!button)return;state.view=button.dataset.view;state.layer=null;app.inert=false;document.querySelectorAll('[data-view]').forEach(item=>item.setAttribute('aria-pressed',String(item===button)));render();});document.addEventListener('keydown',event=>{if(event.key==='Escape'&&state.layer){event.preventDefault();close();}});window.mobileBasicsControlsPrototype={getState:()=>({view:state.view,layer:state.layer,hybrid:{...variants.hybrid},sheets:{...variants.sheets}})};render();
